uniform float amzp_preset;
uniform float amzp_cutoff;
uniform float amzp_range;
uniform float amzp_fade;
uniform float amzp_distortion;
uniform float amzp_frequency;
uniform float amzp_phase;
uniform float amzp_animSpeed;
uniform float amzp_thickness;
uniform float amzp_pitch;
uniform float amzp_density;
uniform float amzp_decay;
uniform float amzp_glow;
uniform float amzp_orientation;
uniform float amzp_xShift;
uniform float amzp_yShift;
uniform float amzp_generators;
uniform float amzp_compress;
uniform float amzp_colorMode;
uniform float amzp_colorR;
uniform float amzp_colorG;
uniform float amzp_colorB;
uniform float amzp_blend;


        float hashV(float2 p) {
            return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
        }

        float noiseV(float2 p) {
            float2 i = floor(p);
            float2 f = fract(p);
            f = f*f*(3.0-2.0*f);
            return mix(
                mix(hashV(i),           hashV(i+float2(1,0)), f.x),
                mix(hashV(i+float2(0,1)), hashV(i+float2(1,1)), f.x),
                f.y
            );
        }


        float3 rainbow(float t) {
            t = fract(t);
            float r = abs(t * 6.0 - 3.0) - 1.0;
            float g = 2.0 - abs(t * 6.0 - 2.0);
            float b = 2.0 - abs(t * 6.0 - 4.0);
            return clamp(float3(r, g, b), 0.0, 1.0);
        }





        float2 getWaveDisplace(float2 dotIdx, float t) {
            float pr   = float(int(amzp_preset));
            float freq = amzp_frequency * 0.0001;
            float ph   = amzp_phase * 3.14159 / 180.0;
            float spd  = t * amzp_animSpeed;
            float col  = dotIdx.x;
            float row  = dotIdx.y;
            float ori  = float(int(amzp_orientation));
            float2  disp = float2(0.0);


            float axis = (ori < 0.5) ? col : row;

            if (pr < 0.5) {

                float w = sin(axis * freq * 50.0 + spd + ph) * amzp_distortion;
                disp = (ori < 0.5) ? float2(0.0, w) : float2(w, 0.0);

            } else if (pr < 1.5) {

                float w = sign(sin(axis * freq * 50.0 + spd + ph)) * amzp_distortion * 0.5;
                disp = (ori < 0.5) ? float2(0.0, w) : float2(w, 0.0);

            } else if (pr < 2.5) {

                float wx = sin(col * freq * 80.0 + spd + ph)        * amzp_distortion * 0.5
                         + sin(col * freq * 130.0 + spd * 1.3)      * amzp_distortion * 0.3
                         + noiseV(float2(col*freq*10.0, spd*0.3))     * amzp_distortion * 0.2;
                float wy = sin(row * freq * 70.0 + spd * 0.8 + ph)  * amzp_distortion * 0.4
                         + sin(row * freq * 110.0 + spd * 1.1)      * amzp_distortion * 0.3;
                disp = float2(wx, wy);

            } else if (pr < 3.5) {

                float2 center = float2(screen.zw.x / amzp_pitch, screen.zw.y / amzp_pitch) * 0.5;
                float dist  = length(dotIdx - center);
                float w     = sin(dist * freq * 100.0 - spd + ph) * amzp_distortion;
                float2 dir    = normalize(dotIdx - center + float2(0.001));
                disp = dir * w;

            } else if (pr < 4.5) {

                disp = float2(0.0);

            } else if (pr < 5.5) {

                float gc  = floor(col / max(amzp_density, 1.0));
                float gt  = floor(spd * 3.0);
                float rnd = (hashV(float2(gc + gt, row)) * 2.0 - 1.0);
                float fired = step(0.6, hashV(float2(gc, gt + 1.0)));
                disp = float2(rnd * amzp_distortion * 2.0 * fired, 0.0);

            } else if (pr < 6.5) {

                float w = (fract(axis * freq * 30.0 + spd) * 2.0 - 1.0) * amzp_distortion;
                disp = (ori < 0.5) ? float2(0.0, w) : float2(w, 0.0);

            } else if (pr < 7.5) {

                float wx = sin(col * freq * 40.0 + spd)             * amzp_distortion * 0.4
                         + sin(row * freq * 30.0 + spd * 0.7 + ph)  * amzp_distortion * 0.3;
                float wy = sin(row * freq * 40.0 + spd * 0.8)       * amzp_distortion * 0.4
                         + sin(col * freq * 25.0 + spd * 1.1 + ph)  * amzp_distortion * 0.3;
                disp = float2(wx, wy);

            } else {

                float pt  = floor(spd * 2.0);
                float rdx = (hashV(float2(col + pt, row + 0.1)) * 2.0 - 1.0);
                float rdy = (hashV(float2(col + 0.2, row + pt)) * 2.0 - 1.0);
                float burst = step(0.5, hashV(float2(col * 0.1, row * 0.1 + pt)));
                disp = float2(rdx, rdy) * amzp_distortion * burst;
            }


            for (int g = 1; g < 10; g++) {
                if (float(g) >= amzp_generators) break;
                float gf = float(g);
                float gOff = gf * 0.618; 
                disp += disp * sin(gOff * 3.14159 + amzp_animSpeed * time) * 0.2 / gf;
            }

            return disp;
        }

        void amzRender() {
            float2 uv  = amzScreenNorm();
            float t  = time;
            float4 src = amzTexture(0, clamp(uv, 0.0, 1.0));




            float cellSize = amzp_pitch;
            float2 pixelPos  = uv * screen.zw;


            float2 dotIdx  = floor(pixelPos / cellSize);
            float2 cellUV  = fract(pixelPos / cellSize); 






            float2 waveDisp   = getWaveDisplace(dotIdx, t);


            waveDisp += float2(amzp_xShift, amzp_yShift) * 0.01;


            waveDisp *= amzp_compress;


            float2 dotCenter  = (dotIdx + 0.5 + waveDisp) * cellSize / screen.zw;
            dotCenter       = clamp(dotCenter, 0.0, 1.0);




            float3 srcCol  = amzTexture(0, dotCenter).rgb;
            float luma   = dot(srcCol, float3(0.299, 0.587, 0.114));


            float lumaAdj = (luma - amzp_cutoff) / max(amzp_range, 0.001);
            lumaAdj = clamp(lumaAdj, 0.0, 1.0);


            lumaAdj = smoothstep(amzp_fade * 0.3, amzp_fade * 0.3 + 0.2, lumaAdj);


            lumaAdj = pow(lumaAdj, 1.0 + amzp_decay * 0.3);






            float baseRad  = amzp_thickness / cellSize * 0.45;
            baseRad        = clamp(baseRad, 0.01, 0.48);
            float dotRadius = baseRad * lumaAdj;
            dotRadius       = clamp(dotRadius, 0.0, 0.48);




            float2 fromCenter = cellUV - 0.5;
            float dist      = length(fromCenter);


            float dotMask = 1.0 - smoothstep(dotRadius * 0.7, dotRadius, dist);




            float cm = float(int(amzp_colorMode));
            float3 dotColor;

            if (cm < 0.5) {

                dotColor = srcCol;
            } else if (cm < 1.5) {

                dotColor = float3(amzp_colorR, amzp_colorG, amzp_colorB);
            } else {

                float rainbowT = (dotIdx.x + dotIdx.y * 0.3) / (screen.zw.x / cellSize);
                dotColor = rainbow(rainbowT + t * amzp_animSpeed * 0.1);
            }





            float glowRadius = dotRadius + (amzp_glow / cellSize) * 0.3;
            glowRadius       = clamp(glowRadius, dotRadius, 0.8);
            float glowFalloff = 1.0 - smoothstep(dotRadius, glowRadius, dist);
            glowFalloff = glowFalloff * glowFalloff; 





            float3 result = float3(0.0); 


            result += dotColor * glowFalloff * lumaAdj * amzp_glow * 0.15;


            result += dotColor * dotMask * lumaAdj;

            result = clamp(result, 0.0, 1.0);

            amzOutput = float4(mix(src.rgb, result, amzp_blend), src.a);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

